/** The CLI, before a product's actions are written into it (generate.ts cliSource). */
export const CLI_SOURCE: string = "#!/usr/bin/env node\n// A command line tool for one Muse Muse product, generated from its musemuse.json. One file, no dependencies, Node 18+.\n// Built with Muse Muse, a hackathon concept. Not an official Meta product.\n\"use strict\";\n\nconst PRODUCT = /*__MUSE_PRODUCT__*/ { slug: \"example\", name: \"Example\", tagline: \"\", liveUrl: \"http://localhost\", mcpUrl: \"\", actions: [] };\nconst VERSION = \"1.0.0\";\nconst DEFAULT_TIMEOUT_S = 120;\nconst USAGE_ERROR = 2;\nconst CALL_ERROR = 1;\n\nclass UsageError extends Error {}\n\nfunction out(text) {\n  process.stdout.write(`${text}\\n`);\n}\n\nfunction err(text) {\n  process.stderr.write(`${text}\\n`);\n}\n\n/** recipeText and recipe-text both name the field recipeText. */\nfunction flagKey(name) {\n  return name.toLowerCase().replace(/[-_]/g, \"\");\n}\n\nfunction findAction(name) {\n  return PRODUCT.actions.find((a) => a.name === name || a.name === name.replace(/-/g, \"_\"));\n}\n\nfunction fieldsOf(action) {\n  const props = action.input && typeof action.input.properties === \"object\" && action.input.properties ? action.input.properties : {};\n  const required = Array.isArray(action.input && action.input.required) ? action.input.required : [];\n  return Object.keys(props).map((name) => ({ name, schema: props[name] || {}, required: required.includes(name) }));\n}\n\nfunction typeOf(schema) {\n  if (Array.isArray(schema.enum) && schema.enum.length && !schema.type) return typeof schema.enum[0];\n  return Array.isArray(schema.type) ? schema.type.find((t) => t !== \"null\") || \"string\" : schema.type || \"string\";\n}\n\nfunction fieldHint(field) {\n  const type = typeOf(field.schema);\n  const choices = Array.isArray(field.schema.enum) ? ` (${field.schema.enum.join(\", \")})` : \"\";\n  const about = field.schema.description ? `  ${field.schema.description}` : \"\";\n  return `  --${field.name} <${type}>${choices}${field.required ? \" required\" : \"\"}${about}`;\n}\n\nfunction mainHelp() {\n  const lines = [\n    `${PRODUCT.name}${PRODUCT.tagline ? `: ${PRODUCT.tagline}` : \"\"}`,\n    \"\",\n    `Usage: ${PRODUCT.slug} <action> [--field value ...] [--json]`,\n    \"\",\n    \"Actions:\",\n    ...PRODUCT.actions.map((a) => `  ${a.name}  ${a.description}`),\n    \"\",\n    \"Options:\",\n    \"  --help, -h          Show this help, or an action's fields after its name\",\n    \"  --json              Print only JSON. With --help, the actions and their input schemas\",\n    \"  --input <json>      The action's whole input as JSON. '-' reads it from stdin\",\n    \"  --input-file <path> Read the action's input from a JSON file\",\n    `  --timeout <seconds> How long to wait for a reply (default ${DEFAULT_TIMEOUT_S})`,\n    \"  --version           Show the version\",\n    \"\",\n    `It calls the live product at ${PRODUCT.liveUrl}`,\n    \"Built with Muse Muse. Not an official Meta product.\",\n  ];\n  return lines.join(\"\\n\");\n}\n\nfunction actionHelp(action) {\n  const fields = fieldsOf(action);\n  const lines = [`${action.name}: ${action.description}`, \"\", `Usage: ${PRODUCT.slug} ${action.name}${fields.length ? \" [--field value ...]\" : \"\"} [--json]`];\n  if (fields.length) lines.push(\"\", \"Fields:\", ...fields.map(fieldHint));\n  return lines.join(\"\\n\");\n}\n\nfunction coerce(field, raw) {\n  const type = typeOf(field.schema);\n  if (type === \"number\" || type === \"integer\") {\n    const value = Number(raw);\n    if (raw === \"\" || !Number.isFinite(value) || (type === \"integer\" && !Number.isInteger(value))) throw new UsageError(`--${field.name} must be ${type === \"integer\" ? \"a whole number\" : \"a number\"}.`);\n    return value;\n  }\n  if (type === \"boolean\") {\n    if (raw === \"true\") return true;\n    if (raw === \"false\") return false;\n    throw new UsageError(`--${field.name} must be true or false.`);\n  }\n  if (type === \"array\" || type === \"object\") {\n    try {\n      return JSON.parse(raw);\n    } catch {\n      throw new UsageError(`--${field.name} must be JSON.`);\n    }\n  }\n  return raw;\n}\n\nfunction readStdin() {\n  return require(\"node:fs\").readFileSync(0, \"utf8\");\n}\n\nfunction parseInput(text, source) {\n  let value;\n  try {\n    value = JSON.parse(text);\n  } catch {\n    throw new UsageError(`${source} isn't valid JSON.`);\n  }\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new UsageError(`${source} must be a JSON object.`);\n  return value;\n}\n\n/** Splits the arguments after the action into the input and the tool's own options. */\nfunction parseArgs(action, args) {\n  const opts = { json: false, help: false, timeoutS: DEFAULT_TIMEOUT_S };\n  const fields = fieldsOf(action);\n  const byKey = new Map(fields.map((f) => [flagKey(f.name), f]));\n  let input = {};\n  const named = {};\n  for (let i = 0; i < args.length; i++) {\n    const arg = args[i];\n    if (!arg.startsWith(\"--\")) {\n      if (arg === \"-h\") {\n        opts.help = true;\n        continue;\n      }\n      throw new UsageError(`Unexpected argument: ${arg}`);\n    }\n    const eq = arg.indexOf(\"=\");\n    const name = eq > 0 ? arg.slice(2, eq) : arg.slice(2);\n    const inline = eq > 0 ? arg.slice(eq + 1) : undefined;\n    const value = () => {\n      if (inline !== undefined) return inline;\n      if (i + 1 >= args.length) throw new UsageError(`--${name} needs a value.`);\n      return args[++i];\n    };\n    if (name === \"json\") opts.json = true;\n    else if (name === \"help\") opts.help = true;\n    else if (name === \"input\") {\n      const text = value();\n      input = parseInput(text === \"-\" ? readStdin() : text, \"--input\");\n    } else if (name === \"input-file\") {\n      const file = value();\n      let text;\n      try {\n        text = require(\"node:fs\").readFileSync(file, \"utf8\");\n      } catch {\n        throw new UsageError(`Can't read ${file}.`);\n      }\n      input = parseInput(text, file);\n    } else if (name === \"timeout\") {\n      opts.timeoutS = Number(value());\n      if (!(opts.timeoutS > 0)) throw new UsageError(\"--timeout must be a number of seconds.\");\n    } else {\n      const negated = name.startsWith(\"no-\") ? byKey.get(flagKey(name.slice(3))) : undefined;\n      if (negated && typeOf(negated.schema) === \"boolean\") {\n        named[negated.name] = false;\n        continue;\n      }\n      const field = byKey.get(flagKey(name));\n      if (!field) {\n        const known = fields.length ? ` It takes ${fields.map((f) => `--${f.name}`).join(\", \")}.` : \" It takes no fields.\";\n        throw new UsageError(`${action.name} has no field --${name}.${known}`);\n      }\n      const bare = typeOf(field.schema) === \"boolean\" && inline === undefined && (i + 1 >= args.length || args[i + 1].startsWith(\"--\"));\n      named[field.name] = bare ? true : coerce(field, value());\n    }\n  }\n  const body = { ...input, ...named };\n  if (!opts.help) {\n    const missing = fields.filter((f) => f.required && body[f.name] === undefined).map((f) => `--${f.name}`);\n    if (missing.length) throw new UsageError(`${action.name} needs ${missing.join(\", \")}.`);\n  }\n  return { body, opts };\n}\n\nasync function callAction(action, body, timeoutS) {\n  if (typeof fetch !== \"function\") throw new Error(\"This tool needs Node 18 or newer.\");\n  const url = `${PRODUCT.liveUrl.replace(/\\/+$/, \"\")}/api/actions/${encodeURIComponent(action.name)}`;\n  let res;\n  try {\n    res = await fetch(url, {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\", accept: \"application/json\", \"user-agent\": `MuseMuse-CLI/${VERSION}` },\n      body: JSON.stringify(body),\n      redirect: \"error\",\n      signal: AbortSignal.timeout(timeoutS * 1000),\n    });\n  } catch (cause) {\n    const timedOut = cause && (cause.name === \"TimeoutError\" || cause.name === \"AbortError\");\n    return { ok: false, status: null, message: timedOut ? `${action.name} took longer than ${timeoutS} s and was stopped.` : `Couldn't reach ${PRODUCT.name} to run ${action.name}.` };\n  }\n  const text = await res.text();\n  if (!res.ok) return { ok: false, status: res.status, message: `${action.name} failed with HTTP ${res.status}: ${text.slice(0, 2000) || \"(empty body)\"}` };\n  try {\n    return { ok: true, reply: JSON.parse(text) };\n  } catch {\n    return { ok: false, status: res.status, message: `${action.name} returned a reply that isn't JSON: ${text.slice(0, 2000)}` };\n  }\n}\n\nasync function main(argv) {\n  const json = argv.includes(\"--json\");\n  const first = argv.find((a) => a !== \"--json\");\n  if (first === undefined || first === \"--help\" || first === \"-h\" || first === \"help\" || first === \"list\") {\n    if (json) out(JSON.stringify({ name: PRODUCT.name, tagline: PRODUCT.tagline, url: PRODUCT.liveUrl, mcp: PRODUCT.mcpUrl, actions: PRODUCT.actions.map((a) => ({ name: a.name, description: a.description, input: a.input })) }));\n    else out(mainHelp());\n    return first === undefined && !json ? USAGE_ERROR : 0;\n  }\n  if (first === \"--version\") {\n    out(VERSION);\n    return 0;\n  }\n  const action = findAction(first);\n  if (!action) throw new UsageError(`${PRODUCT.slug} has no action called ${first}. Run it with --help to see them.`);\n  const rest = argv.slice(argv.indexOf(first) + 1);\n  const { body, opts } = parseArgs(action, argv.slice(0, argv.indexOf(first)).concat(rest));\n  if (opts.help) {\n    if (opts.json) out(JSON.stringify({ name: action.name, description: action.description, input: action.input }));\n    else out(actionHelp(action));\n    return 0;\n  }\n  const result = await callAction(action, body, opts.timeoutS);\n  if (!result.ok) {\n    if (opts.json) out(JSON.stringify({ error: { message: result.message, status: result.status } }));\n    else err(result.message);\n    return CALL_ERROR;\n  }\n  out(opts.json ? JSON.stringify(result.reply) : JSON.stringify(result.reply, null, 2));\n  return 0;\n}\n\nmain(process.argv.slice(2)).then(\n  (code) => {\n    process.exitCode = code;\n  },\n  (cause) => {\n    const usage = cause instanceof UsageError;\n    if (process.argv.includes(\"--json\")) out(JSON.stringify({ error: { message: cause.message, status: null } }));\n    else err(usage ? `${cause.message}\\nRun ${PRODUCT.slug} --help to see what it takes.` : String(cause.message || cause));\n    process.exitCode = usage ? USAGE_ERROR : CALL_ERROR;\n  },\n);\n";

/** What runs each output against the live product, in the Prove it stage's sandbox. */
export const PROVE_RUNNER_SOURCE: string = "// Prove it (docs/PRODUCT_OUTPUTS.md): runs a product's outputs against the live product, as a person would, with curl and\n// node in a throwaway sandbox. Every command's real output and time go to results.json, which the platform turns into\n// each output's result and the terminal scene Demo Studio records. Written into the sandbox by the platform before each\n// run. No dependencies.\n//   node prove-runner.mjs <spec.json>\nimport { spawn } from \"node:child_process\";\nimport { readFileSync, renameSync, writeFileSync } from \"node:fs\";\nimport path from \"node:path\";\n\nconst OUTPUT_CAP = 64 * 1024;\nconst COMMAND_TIMEOUT_S = 40;\n\nconst spec = JSON.parse(readFileSync(process.argv[2], \"utf8\"));\nconst dir = spec.dir;\nconst resultsPath = path.join(dir, \"results.json\");\nconst results = { startedAt: new Date().toISOString(), finishedAt: null, outputs: {} };\n\nfunction save() {\n  const tmp = `${resultsPath}.tmp`;\n  writeFileSync(tmp, JSON.stringify(results));\n  renameSync(tmp, resultsPath);\n}\n\nconst q = (text) => `'${String(text).replace(/'/g, `'\\\\''`)}'`;\n\n/** Runs one command in bash, combining its output, and never throws. A command that runs too long is stopped. */\nfunction shell(command, timeoutS = COMMAND_TIMEOUT_S) {\n  return new Promise((resolve) => {\n    const started = Date.now();\n    const child = spawn(\"bash\", [\"-c\", command], { cwd: dir, stdio: [\"ignore\", \"pipe\", \"pipe\"], detached: true });\n    let output = \"\";\n    let cut = false;\n    const take = (chunk) => {\n      if (output.length >= OUTPUT_CAP) {\n        cut = true;\n        return;\n      }\n      output += chunk.toString(\"utf8\");\n    };\n    child.stdout.on(\"data\", take);\n    child.stderr.on(\"data\", take);\n    let timedOut = false;\n    const timer = setTimeout(() => {\n      timedOut = true;\n      try {\n        process.kill(-child.pid, \"SIGKILL\");\n      } catch {\n        // Already gone.\n      }\n    }, timeoutS * 1000);\n    const finish = (exitCode) => {\n      clearTimeout(timer);\n      resolve({ command, output: cut ? output.slice(0, OUTPUT_CAP) : output, exitCode, timedOut, seconds: (Date.now() - started) / 1000 });\n    };\n    child.on(\"error\", () => finish(127));\n    child.on(\"close\", (code) => finish(timedOut ? 124 : (code ?? 1)));\n  });\n}\n\n/** Adds a finished command to an output's log and saves, so a stopped run still shows what it did. */\nfunction logStep(result, caption, ran, ok) {\n  result.steps.push({ caption, command: ran.command, output: ran.output, ok, exitCode: ran.exitCode, seconds: ran.seconds });\n  save();\n}\n\nfunction start(id) {\n  const result = { ok: false, steps: [], facts: {} };\n  results.outputs[id] = result;\n  return result;\n}\n\n/** Stands in for a download when the site can't serve the file here (a test run against a site without these routes). */\nasync function getFile(result, caption, url, file) {\n  if (!url) {\n    const ran = await shell(`ls -l ${q(file)}`);\n    result.facts.downloaded = false;\n    logStep(result, \"Find the file, put here directly\", ran, ran.exitCode === 0);\n    return ran.exitCode === 0;\n  }\n  const ran = await shell(`curl -fsSL --max-time 30 ${q(url)} -o ${q(file)} && ls -l ${q(file)}`);\n  result.facts.downloaded = ran.exitCode === 0;\n  logStep(result, caption, ran, ran.exitCode === 0);\n  return ran.exitCode === 0;\n}\n\nfunction parseJson(text) {\n  try {\n    return JSON.parse(text);\n  } catch {\n    return null;\n  }\n}\n\n// The address and body come first: a video shows only the start of a long command, and these say what the call is.\nconst mcpCommand = (body, maxTime = 30) =>\n  `curl -sS -X POST ${q(spec.mcpUrl)} -d ${q(JSON.stringify(body))} -H 'content-type: application/json' -H 'accept: application/json, text/event-stream' --max-time ${maxTime}`;\n\nasync function proveMcp() {\n  const result = start(\"mcp\");\n  result.facts = { listed: [], missing: [], called: [], notCalled: spec.notCalled };\n  const hello = await shell(\n    mcpCommand({\n      jsonrpc: \"2.0\",\n      id: 1,\n      method: \"initialize\",\n      params: { protocolVersion: \"2025-06-18\", capabilities: {}, clientInfo: { name: \"muse-muse-prove-it\", version: \"1.0.0\" } },\n    }),\n  );\n  const server = parseJson(hello.output)?.result?.serverInfo;\n  logStep(result, \"Connect to the MCP server\", hello, Boolean(server));\n  if (!server) {\n    result.facts.error = \"The MCP server didn't answer initialize.\";\n    return;\n  }\n\n  const list = await shell(mcpCommand({ jsonrpc: \"2.0\", id: 2, method: \"tools/list\" }));\n  const tools = parseJson(list.output)?.result?.tools;\n  const listed = Array.isArray(tools) ? tools : [];\n  result.facts.listed = listed.map((t) => t.name);\n  result.facts.missing = spec.actionNames.filter((name) => !result.facts.listed.includes(name));\n  const schemasOk = listed.every((t) => t.inputSchema?.type === \"object\");\n  const listedOk = Array.isArray(tools) && result.facts.missing.length === 0 && schemasOk;\n  logStep(result, `List its tools: ${listed.length} found`, list, listedOk);\n  if (!listedOk) {\n    result.facts.error = result.facts.missing.length ? `tools/list left out ${result.facts.missing.join(\", \")}.` : \"tools/list didn't give a usable list.\";\n    return;\n  }\n\n  let id = 3;\n  for (const call of spec.calls) {\n    const ran = await shell(mcpCommand({ jsonrpc: \"2.0\", id: id++, method: \"tools/call\", params: { name: call.name, arguments: call.args } }, 130), 140);\n    const body = parseJson(ran.output);\n    const toolResult = body?.result;\n    const ok = Boolean(toolResult) && toolResult.isError !== true && Array.isArray(toolResult.content) && toolResult.content.length > 0;\n    const error = ok ? undefined : String(toolResult?.content?.[0]?.text ?? body?.error?.message ?? ran.output).slice(0, 400);\n    result.facts.called.push({ name: call.name, ok, ...(error ? { error } : {}) });\n    logStep(result, `Call ${call.name}`, ran, ok);\n  }\n  const called = result.facts.called;\n  result.ok = called.length === 0 || called.some((c) => c.ok);\n  if (!result.ok) result.facts.error = `Every tool call failed. ${called[0]?.error ?? \"\"}`.trim();\n}\n\nasync function proveCli() {\n  const result = start(\"cli\");\n  result.facts = { actionsInHelp: [], called: null, jsonOk: false };\n  const file = `${spec.slug}.cjs`;\n  if (!(await getFile(result, \"Download the CLI\", spec.downloads?.cli, file))) {\n    result.facts.error = \"The CLI didn't download.\";\n    return;\n  }\n  const help = await shell(`node ${q(file)} --help`);\n  const inHelp = spec.actionNames.filter((name) => help.output.includes(name));\n  result.facts.actionsInHelp = inHelp;\n  const helpOk = help.exitCode === 0 && inHelp.length === spec.actionNames.length;\n  logStep(result, \"Ask it for help\", help, helpOk);\n  if (!helpOk) {\n    result.facts.error = help.exitCode === 0 ? \"--help left out some actions.\" : `--help exited with ${help.exitCode}.`;\n    return;\n  }\n  const listed = await shell(`node ${q(file)} --help --json`);\n  const parsed = parseJson(listed.output);\n  const listOk = listed.exitCode === 0 && Array.isArray(parsed?.actions) && parsed.actions.length === spec.actionNames.length;\n  logStep(result, \"List its actions as JSON\", listed, listOk);\n  if (!listOk) {\n    result.facts.error = \"--help --json didn't print the actions as JSON.\";\n    return;\n  }\n  if (!spec.cliCall) {\n    result.ok = true;\n    return;\n  }\n  const ran = await shell(`node ${q(file)} ${q(spec.cliCall.name)} --input ${q(JSON.stringify(spec.cliCall.args))} --json --timeout 120`, 130);\n  const reply = parseJson(ran.output);\n  const ok = ran.exitCode === 0 && reply !== null && reply?.error === undefined;\n  result.facts.called = spec.cliCall.name;\n  result.facts.jsonOk = ok;\n  logStep(result, `Run ${spec.cliCall.name} and print JSON`, ran, ok);\n  if (!ok) result.facts.error = `${spec.cliCall.name} ended with exit code ${ran.exitCode}. ${String(reply?.error?.message ?? ran.output).slice(0, 300)}`.trim();\n  result.ok = ok;\n}\n\nasync function provePlugin() {\n  const result = start(\"claude_plugin\");\n  const file = `${spec.slug}-claude-plugin.zip`;\n  if (!(await getFile(result, \"Download the plugin\", spec.downloads?.claudePlugin, file))) {\n    result.facts.error = \"The plugin didn't download.\";\n    return;\n  }\n  const ran = await shell(`node prove-check-plugin.mjs ${q(file)} ${q(spec.pluginName)} ${q(spec.mcpUrl)}`);\n  logStep(result, \"Check its manifest and MCP address\", ran, ran.exitCode === 0);\n  result.ok = ran.exitCode === 0;\n  if (!result.ok) result.facts.error = ran.output.trim().split(\"\\n\").filter((l) => l.startsWith(\"FAILED\")).join(\" \").slice(0, 400) || \"The check failed.\";\n}\n\nasync function proveSkillFile() {\n  const result = start(\"skill\");\n  result.facts = { problems: [] };\n  if (!(await getFile(result, \"Download the skill file\", spec.downloads?.skill, \"SKILL.md\"))) {\n    result.facts.error = \"The skill file didn't download.\";\n    return;\n  }\n  const ran = await shell(\"head -n 4 SKILL.md | cut -c1-200\");\n  let text = \"\";\n  try {\n    text = readFileSync(path.join(dir, \"SKILL.md\"), \"utf8\");\n  } catch {\n    // Reported below.\n  }\n  const problems = [];\n  if (!text.startsWith(\"---\\n\")) problems.push(\"it has no front matter\");\n  if (!new RegExp(`^name: ${spec.pluginName}$`, \"m\").test(text)) problems.push(\"its name is wrong\");\n  if (!/^description: \"/m.test(text)) problems.push(\"it has no description\");\n  for (const name of spec.actionNames) if (!text.includes(`/api/actions/${name}`)) problems.push(`it leaves out ${name}`);\n  result.facts.problems = problems;\n  logStep(result, \"Read the skill file\", ran, problems.length === 0);\n  result.ok = problems.length === 0;\n  if (!result.ok) result.facts.error = `The skill file is wrong: ${problems.join(\", \")}.`;\n}\n\nsave();\nfor (const prove of [proveMcp, proveCli, provePlugin, proveSkillFile]) {\n  try {\n    await prove();\n  } catch (err) {\n    console.error(`${prove.name}: ${err}`);\n  }\n  save();\n}\nresults.finishedAt = new Date().toISOString();\nsave();\n";

/** The machine check of the Claude plugin's zip. */
export const PROVE_CHECK_PLUGIN_SOURCE: string = "// Checks a Claude plugin zip by machine: its manifest, its MCP address and its skill, then asks that address for its tools.\n//   node prove-check-plugin.mjs <plugin.zip> <name> <mcp url>\nimport { readFileSync } from \"node:fs\";\nimport { inflateRawSync } from \"node:zlib\";\n\nconst [zipPath, name, mcpUrl] = process.argv.slice(2);\nlet failed = false;\nconst say = (ok, text) => {\n  console.log(`${ok ? \"ok    \" : \"FAILED\"} ${text}`);\n  if (!ok) failed = true;\n};\n\nfunction readZip(zip) {\n  let end = -1;\n  for (let i = zip.length - 22; i >= 0; i--) {\n    if (zip.readUInt32LE(i) === 0x06054b50) {\n      end = i;\n      break;\n    }\n  }\n  if (end < 0) throw new Error(\"it isn't a zip file\");\n  const files = new Map();\n  let at = zip.readUInt32LE(end + 16);\n  for (let n = zip.readUInt16LE(end + 10); n > 0; n--) {\n    const method = zip.readUInt16LE(at + 10);\n    const packed = zip.readUInt32LE(at + 20);\n    const nameLength = zip.readUInt16LE(at + 28);\n    const offset = zip.readUInt32LE(at + 42);\n    const file = zip.subarray(at + 46, at + 46 + nameLength).toString(\"utf8\");\n    const start = offset + 30 + zip.readUInt16LE(offset + 26) + zip.readUInt16LE(offset + 28);\n    const body = zip.subarray(start, start + packed);\n    files.set(file, (method === 8 ? inflateRawSync(body) : body).toString(\"utf8\"));\n    at += 46 + nameLength + zip.readUInt16LE(at + 30) + zip.readUInt16LE(at + 32);\n  }\n  return files;\n}\n\nfunction json(files, file) {\n  try {\n    return JSON.parse(files.get(file) ?? \"\");\n  } catch {\n    return null;\n  }\n}\n\nlet files;\ntry {\n  files = readZip(readFileSync(zipPath));\n} catch (err) {\n  say(false, `can't read the zip: ${err.message}`);\n  process.exit(1);\n}\nfor (const file of files.keys()) console.log(`      ${file}`);\nsay([...files.keys()].every((f) => !f.startsWith(\"/\") && !f.split(\"/\").includes(\"..\")), \"every path stays inside the plugin\");\n\nconst manifest = json(files, \".claude-plugin/plugin.json\");\nsay(manifest?.name === name && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name), `.claude-plugin/plugin.json is named ${name}`);\nsay(typeof manifest?.version === \"string\" && typeof manifest?.description === \"string\", \".claude-plugin/plugin.json has a version and a description\");\n\nconst servers = json(files, \".mcp.json\")?.mcpServers ?? {};\nconst server = servers[name];\nsay(Object.keys(servers).length === 1 && server?.type === \"http\", \".mcp.json has one HTTP server\");\nsay(server?.url === mcpUrl, `.mcp.json points at ${mcpUrl}`);\n\nconst skill = files.get(`skills/${name}/SKILL.md`) ?? \"\";\nsay(skill.startsWith(\"---\\n\") && new RegExp(`^name: ${name}$`, \"m\").test(skill) && /^description: \"/m.test(skill), `skills/${name}/SKILL.md has a name and a description`);\n\ntry {\n  const res = await fetch(server?.url ?? mcpUrl, {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\", accept: \"application/json, text/event-stream\" },\n    body: JSON.stringify({ jsonrpc: \"2.0\", id: 1, method: \"tools/list\" }),\n    signal: AbortSignal.timeout(30_000),\n  });\n  const tools = (await res.json())?.result?.tools;\n  say(res.ok && Array.isArray(tools), `that address answers tools/list with ${Array.isArray(tools) ? tools.length : 0} tools`);\n} catch (err) {\n  say(false, `that address didn't answer: ${err.message}`);\n}\nprocess.exit(failed ? 1 : 0);\n";

/** The terminal scene Demo Studio records. */
export const PROVE_SCENE_SOURCE: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Terminal</title>\n<style>\n/* Text stays 100 px from each side: Demo Studio's lowest zoom on a result, 1.15, crops about 84 px off each side of 1280. */\n* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; background: #0d1117; color: #e6edf3; overflow: hidden; }\nbody { display: flex; flex-direction: column; font: 17px/1.5 \"DejaVu Sans Mono\", \"Liberation Mono\", \"Noto Sans Mono\", ui-monospace, Menlo, monospace; }\nheader { flex: none; display: flex; align-items: baseline; justify-content: space-between; gap: 24px; padding: 14px 100px; background: #161b22; border-bottom: 1px solid #30363d; }\nheader b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\nheader span { color: #9da7b3; font-size: 14px; white-space: nowrap; }\nmain { flex: 1; width: 1080px; min-height: 0; margin: 0 auto; overflow: hidden; padding: 16px 0 24px; }\n.block { margin: 0 0 14px; }\n.cmd { white-space: pre-wrap; overflow-wrap: anywhere; }\n.cmd::before { content: \"$ \"; color: #7ee787; }\n.out { white-space: pre-wrap; overflow-wrap: anywhere; color: #c9d1d9; }\n.out.cut { color: #9da7b3; }\n.took { color: #7ee787; font-size: 15px; }\n.took.bad { color: #ff7b72; }\n.wait { color: #9da7b3; }\n</style>\n</head>\n<body>\n<header><b id=\"title\"></b><span id=\"note\"></span></header>\n<main id=\"main\"></main>\n<script>\n(function () {\n  var main = document.getElementById(\"main\");\n  var scene = null;\n  var pause = function (ms) { return new Promise(function (resolve) { setTimeout(resolve, ms); }); };\n  var keep = function () { main.scrollTop = main.scrollHeight; };\n\n  window.loadScene = function (next) {\n    scene = next;\n    document.getElementById(\"title\").textContent = scene.title;\n    document.getElementById(\"note\").textContent = scene.note;\n    document.title = scene.title;\n  };\n\n  // Types the command, shows it waiting for at most a moment (the real time is printed under the output), then prints\n  // the output it really gave.\n  window.playStep = async function (index) {\n    var step = scene.steps[index];\n    var block = document.createElement(\"div\");\n    block.className = \"block\";\n    main.appendChild(block);\n\n    var cmd = document.createElement(\"div\");\n    cmd.className = \"cmd\";\n    block.appendChild(cmd);\n    var text = step.command;\n    var chunk = Math.max(1, Math.ceil(text.length / 24));\n    for (var at = 0; at < text.length; at += chunk) {\n      cmd.textContent = text.slice(0, at + chunk);\n      keep();\n      await pause(40);\n    }\n\n    var wait = document.createElement(\"div\");\n    wait.className = \"wait\";\n    wait.textContent = \"running\";\n    wait.setAttribute(\"aria-busy\", \"true\");\n    block.appendChild(wait);\n    keep();\n    await pause(Math.min(1200, Math.max(300, step.seconds * 1000)));\n    block.removeChild(wait);\n\n    var out = document.createElement(\"div\");\n    out.className = \"out\";\n    out.textContent = step.lines.join(\"\\n\");\n    if (step.lines.length) block.appendChild(out);\n    var took = document.createElement(\"div\");\n    took.className = \"took\" + (step.ok ? \"\" : \" bad\");\n    took.textContent = (step.ok ? \"ok, \" : \"failed, \") + step.took;\n    block.appendChild(took);\n    keep();\n    await pause(300);\n    keep();\n  };\n})();\n</script>\n</body>\n</html>\n";
